[TOOL_CALL]
{tool => "WebFetch", args => {
  --url "https://techcrunch.com/category/artificial-intelligence/"
  --prompt "Extract the top AI and startup news articles from the last 24-48 hours. For each article include: title, source (TechCrunch), publication date, and a brief summary of the key news. Focus on major AI company developments, funding announcements, product launches, and technical breakthroughs."
}}
[/TOOL_CALL]
[TOOL_CALL]
{tool => "WebFetch", args => {
  --url "https://techcrunch.com/category/startups/"
  --prompt "Extract the top startup news articles from the last 24-48 hours. For each article include: title, source (TechCrunch), publication date, and a brief summary. Focus on AI-related startups, funding rounds, and major product launches."
}}
[/TOOL_CALL]
